# Requires qrc_th_common.py in the same folder.
# A fair comparison reports spread: NARMA2 test NMSE over 8 random reservoirs and 4 input series, against matched baselines.
import numpy as np
from qrc_th_common import *

washout, train, test = 200, 1000, 500
T = washout + train + test

def narma2(s):
    u = s / 2
    y = np.zeros(len(s))
    for t in range(2, len(s)):
        y[t] = 0.4 * y[t-1] + 0.4 * y[t-1] * y[t-2] + 0.6 * u[t-1]**3 + 0.1
    return y

def score(F, y):
    w = ridge_fit(F[washout:washout + train], y[washout:washout + train])
    return nmse(ridge_predict(w, F[washout + train:]), y[washout + train:])

def poly(s, k):
    L = np.array([np.roll(s, d) for d in range(k)]).T
    quad = np.array([L[:, i] * L[:, j] for i in range(k) for j in range(i, k)]).T
    return np.hstack([L, quad, L**3])

res = {"4 qubits, V=5 (20 features)": [], "linear in last 20 inputs (20)": [], "polynomial in last 5 inputs (25)": []}
for in_seed in range(4):
    s = np.random.default_rng(200 + in_seed).uniform(0, 1, T)
    y = narma2(s)
    res["linear in last 20 inputs (20)"].append(score(np.array([np.roll(s, d) for d in range(20)]).T, y))
    res["polynomial in last 5 inputs (25)"].append(score(poly(s, 5), y))
    for hs in range(1, 9):
        F, _ = run(s, n=4, V=5, seed=hs)
        res["4 qubits, V=5 (20 features)"].append(score(F, y))
for k, v in res.items():
    v = np.array(v)
    print(f"{k:36s} runs {len(v):2d}  NMSE mean {v.mean():.3f}  sd {v.std():.3f}  min {v.min():.3f}  max {v.max():.3f}")
